package cz.stochel.ormconvertor.javatests.eclipselink;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A key generated by an identity column, as the JPA builder writes the vocabulary's Auto and Identity (decision 187). */
@Entity
@Table(name = "IdentityKeyeds")
public class IdentityKeyed {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "IdentityKeyedId")
    private Integer identityKeyedId;
}
